import{_ as r,o as t,c as i,a2 as a}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"Introduction","description":"What VitePress Sidebar is: a VitePress plugin that builds the sidebar from your folders and Markdown files, with its main features and real-world use.","frontmatter":{"description":"What VitePress Sidebar is: a VitePress plugin that builds the sidebar from your folders and Markdown files, with its main features and real-world use."},"headers":[],"relativePath":"introduction.md","filePath":"en/introduction.md","lastUpdated":1790211691000}'),s={name:"introduction.md"};function o(n,e,l,d,u,p){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p><strong>VitePress Sidebar</strong> is a plugin for <strong><a href="https://vitepress.dev" target="_blank" rel="noreferrer">VitePress</a></strong> that automatically configures and manages the sidebar of your page with simple settings.</p><ul><li>⚡️ Optimized for the latest version of <strong>VitePress</strong></li><li>⚡️ Easy to use, lots of options to customize to your liking</li><li>⚡️ Lightweight bundle file size</li><li>⚡️ <a href="https://vitepress.dev/reference/default-theme-sidebar#multiple-sidebars" target="_blank" rel="noreferrer">Multiple Sidebars</a> support</li><li>⚡️ <a href="https://vitepress.dev/guide/frontmatter" target="_blank" rel="noreferrer">Frontmatter</a> support</li><li>⚡️ Per-folder <a href="/advanced-usage/configuration-file">configuration file</a> (<code>sidebar.config.json</code>) support</li><li>⚡️ <a href="https://vitepress.dev/guide/routing#dynamic-routes" target="_blank" rel="noreferrer">Dynamic routes</a> support</li><li>⚡️ The sidebar refreshes in the dev server when a page is added or removed</li><li>⚡️ <a href="https://www.typescriptlang.org" target="_blank" rel="noreferrer">TypeScript</a> support</li><li>⚡️ Customize menus for sorting, special character conversion, file and folder filters, and more!</li></ul><h2 id="real-world-uses" tabindex="-1">Real-world Uses <a class="header-anchor" href="#real-world-uses" aria-label="Permalink to &quot;Real-world Uses&quot;">​</a></h2><p><strong>VitePress Sidebar</strong> is utilized in a variety of project environments, including my own web services.</p><ul><li>To explore packages used other than: <a href="https://github.com/jooy2/vitepress-sidebar/network/dependents" target="_blank" rel="noreferrer">https://github.com/jooy2/vitepress-sidebar/network/dependents</a></li></ul>',6)])])}const h=r(s,[["render",o]]);export{c as __pageData,h as default};
